 if(view==='focus'){const cards=b.sections.flatMap(s=>s.cards.map(c=>({...c,section:s.title}))),focused=cards.filter(c=>b.focus.cardIds.includes(c.id));return <><div className="resource-intro"><span>Até <select className="inline-select" aria-label="Limite do foco" value={b.focus.limit} onChange={e=>run({type:'focus',...b.focus,limit:Number(e.target.value) as 1|3|5,cardIds:b.focus.cardIds.slice(0,Number(e.target.value))})}><option value="1">1 nota</option><option value="3">3 notas</option><option value="5">5 notas</option></select> escolhidas por você</span><span className="pill"><Target size={12}/>{focused.length} em foco</span></div>{focused.length?<div className="focus-grid">{focused.map((c,i)=><button className="focus-card" key={c.id} onClick={()=>select(c.id)}><span className="focus-index">0{i+1}</span><span className="eyebrow">{c.section}</span><h2>{c.title}</h2><p>{c.text}</p>{c.firstStep&&<div className="focus-first"><ArrowRight size={14}/>{c.firstStep}</div>}</button>)}</div>:<Empty Icon={Target} title="Escolha um passo possível." text="Selecione uma nota no mapa e adicione-a ao seu foco. A prioridade é sempre sua."/>}<h2 className="resource-subtitle">Outras notas para considerar</h2>{cards.filter(c=>!c.done&&!b.focus.cardIds.includes(c.id)).map(c=><div className="list-item" key={c.id}><div><span className="eyebrow">{c.section} · {c.lane==='now'?'AGORA':'DEPOIS'}</span><button onClick={()=>select(c.id)}><h3>{c.title}</h3></button></div><button className="secondary" disabled={busy||focused.length>=b.focus.limit} onClick={()=>run({type:'focus',...b.focus,cardIds:[...b.focus.cardIds,c.id]})}><Plus size={13}/> Foco</button></div>)}{!cards.length&&<button className="secondary" onClick={b.sections.length?()=>newCard(b.sections[0].id):newArea}><Plus size={14}/>{b.sections.length?'Criar primeira nota':'Criar primeira área'}</button>}</>;}
 if(view==='memories')return <MemoryList key={b.boardId} snapshot={snapshot} run={run} busy={busy}/>;
